// Test fixture dependency. Lives under a committed node_modules/ dir so capwall attributes
// its calls to "fixture-dep". Requires fs at load time — tests must require this module
// INSIDE the patched window (and clear the require cache between windows) so it receives
// the shimmed fs.
const fs = require("fs");
const fsPromises = require("fs/promises");
const path = require("path");

const DATA = path.join(__dirname, "data.txt");

exports.readData = () => fs.readFileSync(DATA, "utf8");
exports.readDataAsync = () => fsPromises.readFile(DATA, "utf8");
exports.writeFile = (target) => fs.writeFileSync(target, "fixture-dep was here\n");
exports.rawReadFileSync = fs.readFileSync; // for testing that uninstall/teardown behaves

// Reads DATA via the ReadStream CONSTRUCTOR (not createReadStream) — the bypass surface.
// Returns a promise of the file contents; rejects if construction is denied.
exports.readViaStreamClass = () =>
  new Promise((resolve, reject) => {
    let stream;
    try {
      stream = new fs.ReadStream(DATA);
    } catch (err) {
      reject(err);
      return;
    }
    let data = "";
    stream.on("data", (c) => (data += c));
    stream.on("end", () => resolve(data));
    stream.on("error", reject);
  });

// Existence probe — must return a boolean, never throw, even when denied.
exports.probeExists = () => fs.existsSync(DATA);

// Reads a process.env key — the anti-exfiltration surface. Attributes to "fixture-dep".
exports.readEnv = (key) => process.env[key];
// Reads via descriptor — the getOwnPropertyDescriptor exfiltration path a prior review found.
exports.readEnvDescriptor = (key) => Object.getOwnPropertyDescriptor(process.env, key);

// M4 capability surfaces, each via require() so the loader registry is exercised.
exports.connect = (host, port) => {
  const net = require("net");
  const socket = net.connect({ host, port });
  socket.on("error", () => {}); // ignore ECONNREFUSED; we only care whether the guard fired
  socket.destroy();
  return socket;
};
exports.spawn = () => require("child_process").spawnSync(process.execPath, ["-e", ""]);
exports.runVm = (code) => require("vm").runInNewContext(code);

// Class/alias egress paths a prior security review found bypassed the guard.
exports.connectViaSocketClass = (host, port) => {
  const net = require("net");
  const s = new net.Socket();
  s.on("error", () => {});
  const r = s.connect({ host, port });
  s.destroy();
  return r;
};
exports.connectViaTls = (host, port) => {
  const tls = require("tls");
  const s = tls.connect({ host, port });
  s.on("error", () => {});
  s.destroy();
  return s;
};
exports.spawnViaChildProcessClass = () => {
  const { ChildProcess } = require("child_process");
  const cp = new ChildProcess();
  return cp.spawn({ file: process.execPath, args: [process.execPath, "-e", ""] });
};
exports.sendViaDgram = (host, port) => {
  const dgram = require("dgram");
  const s = dgram.createSocket("udp4");
  s.send(Buffer.from("x"), port, host, () => s.close());
  return s;
};

// Round-2 review: class-escape / alias egress paths that defeated construct-trap guards.
exports.connectViaSocketConstructorEscape = (host, port) => {
  const s = new (require("net").Socket)();
  s.on("error", () => {});
  new (s.constructor)().connect({ host, port });
};
exports.connectViaSocketPrototype = (host, port) => {
  const net = require("net");
  const s = new net.Socket();
  s.on("error", () => {});
  net.Socket.prototype.connect.call(s, { host, port });
};
exports.spawnViaChildProcessConstructorEscape = () => {
  const { ChildProcess } = require("child_process");
  const c = new ChildProcess();
  return new (c.constructor)().spawn({ file: process.execPath, args: [process.execPath, "-e", ""] });
};
exports.connectViaHttpAgent = (host, port) => {
  const s = new (require("http").Agent)().createConnection({ host, port });
  s.on("error", () => {});
  s.destroy();
};
exports.sendViaDgramSocketClass = (host, port) => {
  const s = new (require("dgram").Socket)("udp4");
  s.send(Buffer.from("x"), port, host, () => s.close());
};
exports.tlsConnectPositional = (port, host) => {
  const s = require("tls").connect(port, host);
  s.on("error", () => {});
  s.destroy();
};
// H1: options object overrides the positional/authority target — must guard the real target.
exports.tlsConnectOverride = (port, host, overrideOpts) => {
  const s = require("tls").connect(port, host, overrideOpts);
  s.on("error", () => {});
  s.destroy();
};
exports.http2ConnectOverride = (authority, overrideOpts) => {
  const s = require("http2").connect(authority, overrideOpts);
  s.on("error", () => {});
  s.destroy();
};
// D: unbound UDP send by a granted dep — Node auto-binds + replays send; must not crash.
exports.sendUdpUnbound = (host, port, cb) => {
  const s = require("dgram").createSocket("udp4");
  s.send(Buffer.from("x"), port, host, (err) => {
    s.close();
    cb(err);
  });
};

// #23: broader fs method surface exercises (table-driven coverage — fs-methods.test.ts).
// Each wraps a single real fs call so the test file controls target paths/flags and asserts
// the resulting decision(s) via the onDecision sink.
exports.mkdtempSync = (prefix) => fs.mkdtempSync(prefix);
exports.cpSync = (src, dest) => fs.cpSync(src, dest);
exports.copyFileSync = (src, dest) => fs.copyFileSync(src, dest);
exports.renameSync = (oldPath, newPath) => fs.renameSync(oldPath, newPath);
exports.linkSync = (existingPath, newPath) => fs.linkSync(existingPath, newPath);
exports.symlinkSync = (target, linkPath) => fs.symlinkSync(target, linkPath);
// Opens then immediately closes (closeSync is fd-based — out of scope, unmediated) so the
// test doesn't leak fds; returns true rather than the fd.
exports.openSync = (target, flags) => {
  const fd = fs.openSync(target, flags);
  fs.closeSync(fd);
  return true;
};
// Watches then immediately closes so the test doesn't leak a watcher handle.
exports.watchDir = (dir) => {
  const w = fs.watch(dir);
  w.close();
  return true;
};
exports.readdirSync = (dir) => fs.readdirSync(dir);
exports.realpathSync = (target) => fs.realpathSync(target);
exports.statSync = (target) => fs.statSync(target);
// Same path, passed as a Buffer / a file:// URL instead of a string (#23 coverage — the
// coercePath byte/URL paths aren't exercised by any *other* method in the existing suite).
exports.statSyncBuffer = (target) => fs.statSync(Buffer.from(target, "utf8"));
exports.statSyncUrl = (target) => fs.statSync(require("url").pathToFileURL(target));

// #15: deep-stack attribution. Builds `depth` nested wrapper frames between fixture-dep's own
// frame and the fs call, so the owning frame sits far down the stack — the shape a promise
// chain / deeply-wrapped utility / DI-compiled pipeline produces in the wild, and exactly what
// can exceed capwall's attribution frame budget (maxFrames) and mis-attribute the read.
//
// The wrappers are built with `new Function` ON PURPOSE: a dynamically-compiled frame reports
// NO filename, so capwall's walk SKIPS it (like a node: internal or native frame) while still
// spending frame budget. Wrappers written inline here would each be a fixture-dep frame at the
// TOP of the stack, attributed on the first step, and the frame budget would never come into
// play — the test would prove nothing.
function buildDeepReader(depth) {
  // Innermost frame does the read, and is itself compiled for the same reason.
  let fn = new Function(
    "fs",
    "file",
    "return function deepRead() { return fs.readFileSync(file, 'utf8'); };",
  )(fs, DATA);
  for (let i = 0; i < depth; i++) {
    fn = new Function("inner", "return function deepWrap() { return inner(); };")(fn);
  }
  return fn;
}
exports.readDataViaDeepStack = (depth) => buildDeepReader(depth)();
// #64: `.prototype.constructor` escapes, one per guarded class in the codebase.
//
// A construct-trap `Proxy` forwards `get` to its target, so `Wrapped.prototype` IS the real
// prototype and `Wrapped.prototype.constructor` IS the real, unguarded class — `new
// (fs.ReadStream.prototype.constructor)(deniedPath)` read any file with the guard never
// firing. Every guarded class is now a guarded SUBCLASS, which owns its own `.prototype`
// whose `.constructor` is the guarded class, so the walk lands back on the guard. These
// helpers exist for the whole family (not only the three converted sites) so a future site
// cannot regress silently.
exports.readViaReadStreamConstructorEscape = (target) => {
  const s = new (fs.ReadStream.prototype.constructor)(target);
  s.on("error", () => {});
  s.destroy();
};
exports.writeViaWriteStreamConstructorEscape = (target) => {
  const s = new (fs.WriteStream.prototype.constructor)(target);
  s.on("error", () => {});
  s.destroy();
};
exports.runVmViaScriptConstructorEscape = (code) => {
  const vm = require("vm");
  return new (vm.Script.prototype.constructor)(code).runInThisContext();
};
// Highest-consequence escape: a worker is a fresh Node context with no shims, so an unguarded
// spawn is a full capability escape, not merely an unmediated call. `eval: true` with an empty
// body keeps the fixture inert if it ever DOES spawn (see AGENTS.md § 8).
exports.spawnWorkerViaConstructorEscape = () => {
  const wt = require("worker_threads");
  const w = new (wt.Worker.prototype.constructor)("", { eval: true });
  w.on("error", () => {});
  return w;
};
exports.connectViaSocketPrototypeConstructorEscape = (host, port) => {
  const net = require("net");
  const s = new (net.Socket.prototype.constructor)();
  s.on("error", () => {});
  s.connect({ host, port });
  s.destroy();
};
exports.connectViaTlsSocketConstructorEscape = (host, port) => {
  const tls = require("tls");
  const s = new (tls.TLSSocket.prototype.constructor)();
  s.on("error", () => {});
  s.connect({ host, port });
  s.destroy();
};
exports.requestViaClientRequestConstructorEscape = (host, port) => {
  const http = require("http");
  const r = new (http.ClientRequest.prototype.constructor)({ host, port });
  r.on("error", () => {});
  r.destroy();
};
exports.connectViaHttpAgentConstructorEscape = (host, port) => {
  const http = require("http");
  const s = new (http.Agent.prototype.constructor)().createConnection({ host, port });
  s.on("error", () => {});
  s.destroy();
};
exports.sendViaDgramSocketConstructorEscape = (host, port) => {
  const dgram = require("dgram");
  const s = new (dgram.Socket.prototype.constructor)("udp4");
  s.send(Buffer.from("x"), port, host, () => s.close());
};
exports.spawnViaChildProcessPrototypeConstructorEscape = () => {
  const cp = require("child_process");
  const c = new (cp.ChildProcess.prototype.constructor)();
  return c.spawn({ file: process.execPath, args: [process.execPath, "-e", ""] });
};

// #64 compatibility (non-adversarial shapes must be unaffected by the subclass conversion).
// Writes via the WriteStream CONSTRUCTOR, mirroring readViaStreamClass.
exports.writeViaStreamClass = (target) =>
  new Promise((resolve, reject) => {
    let stream;
    try {
      stream = new fs.WriteStream(target);
    } catch (err) {
      reject(err);
      return;
    }
    stream.on("error", reject);
    stream.on("close", () => resolve(true));
    stream.end("fixture-dep was here\n");
  });

// A real package subclassing fs.ReadStream further (common in the ecosystem) must keep
// working, keep `instanceof` honest in BOTH directions, and still be guarded.
exports.readViaOwnReadStreamSubclass = (target) =>
  new Promise((resolve, reject) => {
    class MyReadStream extends fs.ReadStream {}
    let stream;
    try {
      stream = new MyReadStream(target);
    } catch (err) {
      reject(err);
      return;
    }
    if (!(stream instanceof MyReadStream) || !(stream instanceof fs.ReadStream)) {
      reject(new Error("instanceof broken for a further subclass"));
      return;
    }
    let data = "";
    stream.on("data", (c) => (data += c));
    stream.on("end", () => resolve(data));
    stream.on("error", reject);
  });

// Observable shape of the guarded stream classes, probed from inside a dependency (so the
// shimmed `fs` is the one under test). Returns booleans the test asserts individually.
exports.streamClassShape = () => {
  const { Readable } = require("stream");
  const created = fs.createReadStream(DATA); // real ReadStream, built by Node's own factory
  created.on("error", () => {});
  created.destroy();
  const direct = new fs.ReadStream(DATA);
  direct.on("error", () => {});
  direct.destroy();
  class Sub extends fs.ReadStream {}
  const sub = new Sub(DATA);
  sub.on("error", () => {});
  sub.destroy();
  let protoReachesReadable = false;
  for (let p = Object.getPrototypeOf(direct); p !== null; p = Object.getPrototypeOf(p)) {
    if (p === Readable.prototype) protoReachesReadable = true;
  }
  return {
    // A factory-built REAL stream must still satisfy `instanceof` the guarded class.
    createdInstanceOfGuarded: created instanceof fs.ReadStream,
    directInstanceOfGuarded: direct instanceof fs.ReadStream,
    // `.constructor` must be the GUARDED class, not the real one — that is the whole fix.
    directConstructorIsGuarded: direct.constructor === fs.ReadStream,
    prototypeConstructorIsGuarded: fs.ReadStream.prototype.constructor === fs.ReadStream,
    // The deprecated aliases are the SAME object as their primary, exactly like real fs.
    readAliasIdentity: fs.FileReadStream === fs.ReadStream,
    writeAliasIdentity: fs.FileWriteStream === fs.WriteStream,
    name: fs.ReadStream.name,
    protoReachesReadable,
    // A further subclass keeps ordinary instanceof semantics in BOTH directions: its own
    // instances match, and an unrelated real stream does NOT (a naive hasInstance override
    // inherited down the static chain would wrongly say true here).
    subInstanceOfSub: sub instanceof Sub,
    createdNotInstanceOfSub: !(created instanceof Sub),
  };
};

// #66: the process.env write/delete/define trap surface, driven from a dependency so every
// call attributes to "fixture-dep". Each helper isolates ONE trap path so env-traps.test.ts
// can compare it against un-shimmed process.env and assert what gets recorded.
//
// setEnv deliberately does not read the key back: a read-back would go through the gated `get`
// trap and record a decision, which would muddy the "writes are not recorded" assertion. The
// test reads the value itself (test-file reads attribute to <app>, ungated).
exports.setEnv = (key, value) => {
  process.env[key] = value;
};
exports.assignEnv = (key, value) => {
  Object.assign(process.env, { [key]: value });
};
// Read-modify-write: `get` then `set` on the same key — the compound-assignment path.
exports.appendEnv = (key, suffix) => {
  process.env[key] += suffix;
};
// Symbol key: must behave exactly like un-shimmed process.env (throws on string coercion).
exports.setEnvSymbol = () => {
  process.env[Symbol("capwall-test")] = "v";
};
exports.deleteEnv = (key) => delete process.env[key];
// Full data descriptor — the only shape Node's process.env accepts.
exports.defineEnv = (key, value) => {
  Object.defineProperty(process.env, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  });
};
// Partial descriptor — rejected by un-shimmed process.env too; asserts parity, not a capwall rule.
exports.definePartialEnv = (key, value) => {
  Object.defineProperty(process.env, key, { value });
};
exports.hasEnv = (key) => key in process.env;
